<body>
  <div id="app"></div>

  <script>
    const state = {
      isDialogOpen: false,
      imageDeleted: false
    };

    const image = {
      title: "Golden Hour Coastline",
      alt: "Ocean waves rolling toward a golden beach at sunset",
      src: "https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1200&q=80",
      collection: "Travel Library",
      size: "14.2 MB",
      dimensions: "4280 x 2848"
    };

    function escapeHtml(value) {
      return String(value)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");
    }

    function Button({ className = "", label, type = "button", dataAction = "", disabled = false }) {
      return `
        <button
          type="${type}"
          class="button ${className}".trim()
          ${dataAction ? `data-action="${dataAction}"` : ""}
          ${disabled ? "disabled" : ""}
        >
          ${escapeHtml(label)}
        </button>
      `;
    }

    function MetaCard({ label, value }) {
      return `
        <div class="meta-card">
          <span class="meta-label">${escapeHtml(label)}</span>
          <span class="meta-value">${escapeHtml(value)}</span>
        </div>
      `;
    }

    function PreviewCard() {
      return `
        <section class="preview-card" aria-label="Image preview">
          <div class="image-panel">
            <div class="image-frame">
              <span class="image-chip">Library preview</span>
              <img src="${escapeHtml(image.src)}" alt="${escapeHtml(image.alt)}">
            </div>
          </div>
          <aside class="details-panel">
            <div>
              <p class="eyebrow">Asset details</p>
              <h1>${escapeHtml(image.title)}</h1>
              <p class="description">
                Review the image before organizing or removing it from your saved library.
              </p>
              <div class="meta-grid">
                ${MetaCard({ label: "Collection", value: image.collection })}
                ${MetaCard({ label: "File size", value: image.size })}
                ${MetaCard({ label: "Resolution", value: image.dimensions })}
                ${MetaCard({ label: "Status", value: state.imageDeleted ? "Removed" : "Available" })}
              </div>
            </div>
            <div>
              <div class="actions">
                ${Button({ className: "button-secondary", label: "Download", dataAction: "download", disabled: state.imageDeleted })}
                ${Button({ className: "button-danger trigger", label: state.imageDeleted ? "Deleted" : "Delete image", dataAction: "open-dialog", disabled: state.imageDeleted })}
              </div>
              <div class="status" aria-live="polite">
                ${state.imageDeleted ? "The image has been removed from your library." : ""}
              </div>
            </div>
          </aside>
        </section>
      `;
    }

    function ConfirmDialog() {
      return `
        <div class="dialog-root" ${state.isDialogOpen ? "" : "hidden"}>
          <div class="dialog-backdrop" data-action="close-dialog"></div>
          <section
            class="dialog"
            role="dialog"
            aria-modal="true"
            aria-labelledby="dialog-title"
            aria-describedby="dialog-description"
          >
            <div class="dialog-icon" aria-hidden="true">
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
                <path d="M10 11V17M14 11V17M4 7H20M18 7L17.125 18.059C17.0441 19.0818 16.1904 19.875 15.1644 19.875H8.83562C7.80957 19.875 6.9559 19.0818 6.875 18.059L6 7M9 7V4.75C9 4.33579 9.33579 4 9.75 4H14.25C14.6642 4 15 4.33579 15 4.75V7" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>
              </svg>
            </div>
            <h2 id="dialog-title">Delete this image?</h2>
            <p id="dialog-description">
              This will permanently remove <strong>${escapeHtml(image.title)}</strong> from your library.
              You can’t undo this action.
            </p>
            <div class="dialog-actions">
              ${Button({ className: "button-ghost", label: "Cancel", dataAction: "close-dialog" })}
              ${Button({ className: "button-confirm", label: "Delete image", dataAction: "confirm-delete" })}
            </div>
          </section>
        </div>
      `;
    }

    function App() {
      return `
        <main class="page-shell">
          ${PreviewCard()}
          ${ConfirmDialog()}
        </main>
      `;
    }

    function render() {
      document.getElementById("app").innerHTML = App();

      if (state.isDialogOpen) {
        const cancelButton = document.querySelector('[data-action="close-dialog"] + .dialog, .dialog [data-action="close-dialog"]');
        const dialogButton = document.querySelector('.dialog [data-action="close-dialog"]');
        if (dialogButton) {
          dialogButton.focus();
        }
      }
    }

    document.addEventListener("click", (event) => {
      const action = event.target.closest("[data-action]")?.dataset.action;
      if (!action) {
        return;
      }

      if (action === "open-dialog") {
        state.isDialogOpen = true;
        render();
      } else if (action === "close-dialog") {
        state.isDialogOpen = false;
        render();
      } else if (action === "confirm-delete") {
        state.isDialogOpen = false;
        state.imageDeleted = true;
        render();
      }
    });

    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape" && state.isDialogOpen) {
        state.isDialogOpen = false;
        render();
      }
    });

    render();
  </script>
</body>
