      --overlay: rgba(15, 23, 42, 0.54);
      --radius-xl: 28px;
      --radius-lg: 20px;
      --radius-md: 14px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top left, rgba(37, 99, 235, 0.18), transparent 28%),
        radial-gradient(circle at right, rgba(14, 165, 233, 0.16), transparent 24%),
        var(--bg);
      color: var(--text);
    }

    button,
    input,
    textarea,
    select {
      font: inherit;
    }

    .page-shell {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 32px 20px;
    }

    .preview-card {
      width: min(100%, 980px);
      display: grid;
      grid-template-columns: minmax(0, 1.2fr) minmax(280px, 0.8fr);
      gap: 28px;
      padding: 28px;
      border: 1px solid rgba(255, 255, 255, 0.65);
      border-radius: var(--radius-xl);
      background: var(--panel);
      backdrop-filter: blur(18px);
      box-shadow: var(--shadow);
    }

    .image-panel,
    .details-panel {
      background: var(--panel-strong);
      border: 1px solid var(--line);
      border-radius: calc(var(--radius-xl) - 8px);
      box-shadow: var(--shadow-soft);
    }

    .image-panel {
      padding: 18px;
    }

    .image-frame {
      position: relative;
      overflow: hidden;
      border-radius: 18px;
      aspect-ratio: 4 / 3;
      background: linear-gradient(140deg, #dbeafe, #f8fafc 42%, #e2e8f0);
    }

    .image-frame img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
    }

    .image-chip {
      position: absolute;
      top: 16px;
      left: 16px;
      padding: 8px 12px;
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.92);
      color: var(--text);
      font-size: 0.85rem;
      font-weight: 600;
      box-shadow: 0 8px 24px rgba(15, 23, 42, 0.12);
    }

    .details-panel {
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      padding: 28px;
    }

    .eyebrow {
      margin: 0 0 10px;
      color: var(--primary);
      text-transform: uppercase;
      letter-spacing: 0.12em;
      font-size: 0.76rem;
      font-weight: 700;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 3vw, 2.7rem);
      line-height: 1.05;
      letter-spacing: -0.04em;
    }

    .description {
      margin: 14px 0 0;
      color: var(--muted);
      line-height: 1.6;
      font-size: 1rem;
    }

    .meta-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 14px;
      margin: 28px 0;
    }

    .meta-card {
      padding: 16px;
      border-radius: var(--radius-md);
      background: #f8fafc;
      border: 1px solid var(--line);
    }

    .meta-label {
      display: block;
      color: var(--muted);
      font-size: 0.8rem;
      margin-bottom: 8px;
    }

    .meta-value {
      font-weight: 700;
      letter-spacing: -0.02em;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
      margin-top: 12px;
    }

    .button {
      appearance: none;
      border: 0;
      border-radius: 999px;
      padding: 14px 20px;
      font-weight: 700;
      cursor: pointer;
      transition: transform 0.18s ease, box-shadow 0.18s ease, background-color 0.18s ease;
    }

    .button:hover {
      transform: translateY(-1px);
    }

    .button:focus-visible {
      outline: 3px solid rgba(37, 99, 235, 0.28);
      outline-offset: 3px;
    }

    .button-secondary {
      background: var(--primary-soft);
      color: var(--primary);
    }

    .button-secondary:hover {
      box-shadow: 0 10px 24px rgba(37, 99, 235, 0.16);
    }

    .button-danger {
      background: #fee2e2;
      color: var(--danger-dark);
    }

    .button-danger:hover {
      box-shadow: 0 12px 24px rgba(220, 38, 38, 0.16);
    }

    .dialog-root[hidden] {
      display: none;
    }

    .dialog-root {
      position: fixed;
      inset: 0;
      display: grid;
      place-items: center;
      padding: 20px;
      z-index: 20;
    }

    .dialog-backdrop {
      position: absolute;
      inset: 0;
      background: var(--overlay);
      backdrop-filter: blur(6px);
    }

    .dialog {
      position: relative;
      width: min(100%, 440px);
      padding: 28px;
      border-radius: 24px;
      background: #ffffff;
      border: 1px solid rgba(226, 232, 240, 0.95);
      box-shadow: 0 30px 80px rgba(15, 23, 42, 0.24);
    }

    .dialog-icon {
      width: 52px;
      height: 52px;
      display: inline-grid;
      place-items: center;
      border-radius: 16px;
      background: #fee2e2;
      color: var(--danger);
      margin-bottom: 18px;
    }

    .dialog h2 {
      margin: 0;
      font-size: 1.45rem;
      letter-spacing: -0.03em;
    }

    .dialog p {
      margin: 12px 0 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 12px;
      margin-top: 28px;
    }

    .button-ghost {
      background: #f8fafc;
      color: var(--text);
      border: 1px solid var(--line);
    }

    .button-confirm {
      background: var(--danger);
      color: #ffffff;
    }

    .button-confirm:hover {
      background: var(--danger-dark);
      box-shadow: 0 14px 28px rgba(185, 28, 28, 0.24);
    }

    .status {
      margin-top: 18px;
      min-height: 1.5em;
      color: var(--primary);
      font-weight: 600;
    }

    @media (max-width: 840px) {
      .preview-card {
        grid-template-columns: 1fr;
      }
    }

    @media (max-width: 520px) {
      .preview-card,
      .details-panel,
      .dialog {
        padding: 20px;
      }

      .meta-grid {
        grid-template-columns: 1fr;
      }

      .actions,
      .dialog-actions {
        flex-direction: column;
      }

      .actions .button,
      .dialog-actions .button {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <div id="app"></div>

  <script>
    const state = {
      isDialogOpen: false,
      imageDeleted: false
    };

    const image = {
      title: "Golden Hour Coastline",
      alt: "Ocean waves rolling toward a golden beach at sunset",
      src: "https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1200&q=80",
      collection: "Travel Library",
      size: "14.2 MB",
      dimensions: "4280 x 2848"
    };

    function escapeHtml(value) {
      return String(value)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");
    }

    function Button({ className = "", label, type = "button", dataAction = "", disabled = false }) {
      return `
        <button
          type="${type}"
          class="button ${className}".trim()
          ${dataAction ? `data-action="${dataAction}"` : ""}
          ${disabled ? "disabled" : ""}
        >
          ${escapeHtml(label)}
        </button>
      `;
    }

    function MetaCard({ label, value }) {
      return `
        <div class="meta-card">
          <span class="meta-label">${escapeHtml(label)}</span>
          <span class="meta-value">${escapeHtml(value)}</span>
        </div>
      `;
    }

    function PreviewCard() {
      return `
        <section class="preview-card" aria-label="Image preview">
          <div class="image-panel">
            <div class="image-frame">
              <span class="image-chip">Library preview</span>
              <img src="${escapeHtml(image.src)}" alt="${escapeHtml(image.alt)}">
            </div>
          </div>
          <aside class="details-panel">
            <div>
              <p class="eyebrow">Asset details</p>
              <h1>${escapeHtml(image.title)}</h1>
              <p class="description">
                Review the image before organizing or removing it from your saved library.
              </p>
              <div class="meta-grid">
                ${MetaCard({ label: "Collection", value: image.collection })}
                ${MetaCard({ label: "File size", value: image.size })}
                ${MetaCard({ label: "Resolution", value: image.dimensions })}
                ${MetaCard({ label: "Status", value: state.imageDeleted ? "Removed" : "Available" })}
              </div>
            </div>
            <div>
              <div class="actions">
                ${Button({ className: "button-secondary", label: "Download", dataAction: "download", disabled: state.imageDeleted })}
                ${Button({ className: "button-danger trigger", label: state.imageDeleted ? "Deleted" : "Delete image", dataAction: "open-dialog", disabled: state.imageDeleted })}
              </div>
              <div class="status" aria-live="polite">
                ${state.imageDeleted ? "The image has been removed from your library." : ""}
              </div>
            </div>
          </aside>
        </section>
      `;
    }

    function ConfirmDialog() {
      return `
        <div class="dialog-root" ${state.isDialogOpen ? "" : "hidden"}>
          <div class="dialog-backdrop" data-action="close-dialog"></div>
          <section
            class="dialog"
            role="dialog"
            aria-modal="true"
            aria-labelledby="dialog-title"
            aria-describedby="dialog-description"
          >
            <div class="dialog-icon" aria-hidden="true">
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
                <path d="M10 11V17M14 11V17M4 7H20M18 7L17.125 18.059C17.0441 19.0818 16.1904 19.875 15.1644 19.875H8.83562C7.80957 19.875 6.9559 19.0818 6.875 18.059L6 7M9 7V4.75C9 4.33579 9.33579 4 9.75 4H14.25C14.6642 4 15 4.33579 15 4.75V7" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>
              </svg>
            </div>
            <h2 id="dialog-title">Delete this image?</h2>
            <p id="dialog-description">
              This will permanently remove <strong>${escapeHtml(image.title)}</strong> from your library.
              You can’t undo this action.
            </p>
            <div class="dialog-actions">
              ${Button({ className: "button-ghost", label: "Cancel", dataAction: "close-dialog" })}
              ${Button({ className: "button-confirm", label: "Delete image", dataAction: "confirm-delete" })}
            </div>
          </section>
        </div>
      `;
    }

    function App() {
      return `
        <main class="page-shell">
          ${PreviewCard()}
          ${ConfirmDialog()}
        </main>
      `;
    }

    function render() {
      document.getElementById("app").innerHTML = App();

      if (state.isDialogOpen) {
        const cancelButton = document.querySelector('[data-action="close-dialog"] + .dialog, .dialog [data-action="close-dialog"]');
        const dialogButton = document.querySelector('.dialog [data-action="close-dialog"]');
        if (dialogButton) {
          dialogButton.focus();
        }
      }
    }

    document.addEventListener("click", (event) => {
      const action = event.target.closest("[data-action]")?.dataset.action;
      if (!action) {
        return;
      }

      if (action === "open-dialog") {
        state.isDialogOpen = true;
        render();
      } else if (action === "close-dialog") {
        state.isDialogOpen = false;
        render();
      } else if (action === "confirm-delete") {
        state.isDialogOpen = false;
        state.imageDeleted = true;
        render();
      }
    });

    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape" && state.isDialogOpen) {
        state.isDialogOpen = false;
        render();
      }
    });

    render();
  </script>
</body>
</html>
